package com.afirma.assina;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import java.util.*;
import java.net.http.*;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;
import org.springframework.jdbc.core.namedparam.*;
import tools.jackson.databind.ObjectMapper;

class ProvedoresFirmaTest {
 private final ObjectMapper json=new ObjectMapper();
 private static String corpo(HttpRequest request)throws Exception{var f=new CompletableFuture<String>();var bytes=new java.io.ByteArrayOutputStream();request.bodyPublisher().orElseThrow().subscribe(new java.util.concurrent.Flow.Subscriber<ByteBuffer>(){public void onSubscribe(java.util.concurrent.Flow.Subscription s){s.request(Long.MAX_VALUE);}public void onNext(ByteBuffer b){byte[] v=new byte[b.remaining()];b.get(v);bytes.writeBytes(v);}public void onError(Throwable e){f.completeExceptionally(e);}public void onComplete(){f.complete(bytes.toString(StandardCharsets.UTF_8));}});return f.get(3,TimeUnit.SECONDS);}
 @Test void enviaContextoEInterpretaRespostaChatGptSemAcessarRede()throws Exception{var banco=mock(NamedParameterJdbcTemplate.class);var http=mock(HttpClient.class);var resposta=mock(HttpResponse.class);var env=new MockEnvironment().withProperty("APP_IA_TOKEN_TESTE","token-local-de-teste-com-mais-de-20-caracteres");when(banco.queryForMap(anyString(),any(MapSqlParameterSource.class))).thenReturn(Map.of("provedor","OPENAI","modelo","modelo-teste","instrucoes","Ajude com os contratos","referencia_segredo","APP_IA_TOKEN_TESTE","temperatura",0.3,"limite_resposta",500));when(banco.queryForList(anyString(),any(MapSqlParameterSource.class))).thenReturn(List.of(Map.of("sentido","ENTRADA","texto","Quero assinar")));when(resposta.statusCode()).thenReturn(200);when(resposta.body()).thenReturn("{\"choices\":[{\"message\":{\"content\":\"Vamos preparar seu contrato.\"}}]}");when(http.send(any(HttpRequest.class),any(HttpResponse.BodyHandler.class))).thenReturn(resposta);var ia=new ServicoInteligenciaConversacional(banco,json,env,http);assertEquals("Vamos preparar seu contrato.",ia.responder(1,2,UUID.randomUUID()));var captor=org.mockito.ArgumentCaptor.forClass(HttpRequest.class);verify(http).send(captor.capture(),any(HttpResponse.BodyHandler.class));var r=captor.getValue();assertEquals("https://api.openai.com/v1/chat/completions",r.uri().toString());var enviado=json.readTree(corpo(r));assertEquals("Quero assinar",enviado.path("messages").path(1).path("content").asText());assertEquals("modelo-teste",enviado.path("model").asText());}
 @Test void modeloMetaIncluiVariaveisEEsperaIdentificadorDoProvedor()throws Exception{var banco=mock(NamedParameterJdbcTemplate.class);var http=mock(HttpClient.class);var resposta=mock(HttpResponse.class);var env=new MockEnvironment().withProperty("APP_META_TOKEN_TESTE","token-meta-de-teste-com-mais-de-20-caracteres");when(banco.queryForMap(anyString(),any(MapSqlParameterSource.class))).thenReturn(Map.of("identificador_meta","1234567890","referencia_segredo_meta","APP_META_TOKEN_TESTE"));when(resposta.statusCode()).thenReturn(200);when(resposta.body()).thenReturn("{\"messages\":[{\"id\":\"wamid.teste\"}]}");when(http.send(any(HttpRequest.class),any(HttpResponse.BodyHandler.class))).thenReturn(resposta);var meta=new ServicoCanalOficial(banco,json,env,"v23.0",http);assertEquals("wamid.teste",meta.enviarModelo(UUID.randomUUID(),"5511999990000","contrato_pronto","pt_BR",List.of(Map.of("type","text","text","Ana"))));var cap=org.mockito.ArgumentCaptor.forClass(HttpRequest.class);verify(http).send(cap.capture(),any(HttpResponse.BodyHandler.class));var enviado=json.readTree(corpo(cap.getValue()));assertEquals("template",enviado.path("type").asText());assertEquals("Ana",enviado.path("template").path("components").path(0).path("parameters").path(0).path("text").asText());}
 @Test void timeoutDeEnvioNaoPodeVirarConfirmacaoOuRepeticaoAutomatica()throws Exception{var banco=mock(NamedParameterJdbcTemplate.class);var http=mock(HttpClient.class);var env=new MockEnvironment().withProperty("APP_META_TOKEN_TESTE","token-meta-de-teste-com-mais-de-20-caracteres");when(banco.queryForMap(anyString(),any(MapSqlParameterSource.class))).thenReturn(Map.of("identificador_meta","1234567890","referencia_segredo_meta","APP_META_TOKEN_TESTE"));when(http.send(any(HttpRequest.class),any(HttpResponse.BodyHandler.class))).thenThrow(new HttpTimeoutException("timeout simulado"));var meta=new ServicoCanalOficial(banco,json,env,"v23.0",http);assertThrows(EntregaIndeterminada.class,()->meta.enviar(UUID.randomUUID(),"5511999990000","Texto de teste"));}
}
